-- Typed relational projections maintained in the same transaction as replication envelopes.
CREATE TABLE IF NOT EXISTS asset_types(id text PRIMARY KEY CHECK(id IN ('movable','immovable')),name_th text NOT NULL);
INSERT INTO asset_types VALUES('movable','สังหาริมทรัพย์'),('immovable','อสังหาริมทรัพย์') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS asset_categories(id uuid PRIMARY KEY,temple_id uuid NOT NULL REFERENCES temples(id),name text NOT NULL,type_id text NOT NULL REFERENCES asset_types(id),parent_id uuid,active boolean NOT NULL DEFAULT true,UNIQUE(temple_id,id),FOREIGN KEY(temple_id,parent_id) REFERENCES asset_categories(temple_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS category_custom_fields(id uuid PRIMARY KEY,temple_id uuid NOT NULL,category_id uuid NOT NULL,label text NOT NULL,field_type text NOT NULL DEFAULT 'text',ordinal integer NOT NULL,FOREIGN KEY(temple_id,category_id) REFERENCES asset_categories(temple_id,id),UNIQUE(category_id,label));
CREATE TABLE IF NOT EXISTS locations(id uuid PRIMARY KEY,temple_id uuid NOT NULL REFERENCES temples(id),name text NOT NULL,parent_id uuid,active boolean NOT NULL DEFAULT true,UNIQUE(temple_id,id),FOREIGN KEY(temple_id,parent_id) REFERENCES locations(temple_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS assets(id uuid PRIMARY KEY,temple_id uuid NOT NULL REFERENCES temples(id),code text NOT NULL,name text NOT NULL,type_id text NOT NULL REFERENCES asset_types(id),category_id uuid NOT NULL,location_id uuid NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),unit text NOT NULL,unit_value numeric CHECK(unit_value>=0),acquisition_date date,acquisition_method text NOT NULL,custodian text NOT NULL,condition text NOT NULL,status text NOT NULL,description text NOT NULL,source text NOT NULL,notes text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL,created_by uuid NOT NULL REFERENCES users(id),updated_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz,UNIQUE(temple_id,id),UNIQUE(temple_id,code),FOREIGN KEY(temple_id,category_id) REFERENCES asset_categories(temple_id,id),FOREIGN KEY(temple_id,location_id) REFERENCES locations(temple_id,id));
CREATE TABLE IF NOT EXISTS asset_registration(asset_id uuid PRIMARY KEY,temple_id uuid NOT NULL,registration_number text,registration_date date,title_document text,property_location text,area text,additional_fields jsonb NOT NULL DEFAULT '{}',FOREIGN KEY(temple_id,asset_id) REFERENCES assets(temple_id,id));
CREATE TABLE IF NOT EXISTS inventory_sessions(id uuid PRIMARY KEY,temple_id uuid NOT NULL REFERENCES temples(id),name text NOT NULL,location_id uuid,status text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(temple_id,id),FOREIGN KEY(temple_id,location_id) REFERENCES locations(temple_id,id));
CREATE TABLE IF NOT EXISTS inventory_session_items(session_id uuid NOT NULL,temple_id uuid NOT NULL,asset_id uuid NOT NULL,result text NOT NULL,note text NOT NULL,PRIMARY KEY(session_id,asset_id),FOREIGN KEY(temple_id,session_id) REFERENCES inventory_sessions(temple_id,id),FOREIGN KEY(temple_id,asset_id) REFERENCES assets(temple_id,id));
CREATE INDEX IF NOT EXISTS assets_location ON assets(temple_id,location_id);
CREATE INDEX IF NOT EXISTS assets_category ON assets(temple_id,category_id);
CREATE INDEX IF NOT EXISTS assets_status ON assets(temple_id,status,condition);
CREATE INDEX IF NOT EXISTS locations_parent ON locations(temple_id,parent_id);
-- Phase 3/4 lifecycle and report schemas; no approval endpoint is enabled yet.
CREATE TABLE IF NOT EXISTS asset_status_events(id uuid PRIMARY KEY,temple_id uuid NOT NULL,asset_id uuid NOT NULL,status text NOT NULL,reason text NOT NULL,operator_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(temple_id,asset_id) REFERENCES assets(temple_id,id));
CREATE TABLE IF NOT EXISTS asset_disposal_requests(id uuid PRIMARY KEY,temple_id uuid NOT NULL,asset_id uuid NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),reason text NOT NULL,disposal_date date,status text NOT NULL DEFAULT 'pending',requested_by uuid NOT NULL REFERENCES users(id),approved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,FOREIGN KEY(temple_id,asset_id) REFERENCES assets(temple_id,id));
CREATE TABLE IF NOT EXISTS export_templates(id text PRIMARY KEY,version text NOT NULL,asset_type text REFERENCES asset_types(id),source_sha256 text NOT NULL,validation_status text NOT NULL DEFAULT 'unvalidated',mapping jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS export_history(id uuid PRIMARY KEY,temple_id uuid NOT NULL REFERENCES temples(id),template_id text REFERENCES export_templates(id),created_by uuid NOT NULL REFERENCES users(id),format text NOT NULL,record_ids jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE tab text; BEGIN
FOREACH tab IN ARRAY ARRAY['asset_categories','category_custom_fields','locations','assets','asset_registration','inventory_sessions','inventory_session_items','asset_status_events','asset_disposal_requests','export_history'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);
EXECUTE format('DROP POLICY IF EXISTS tenant_scope ON %I',tab);
EXECUTE format('CREATE POLICY tenant_scope ON %I USING (temple_id::text=current_setting(''app.temple_id'',true)) WITH CHECK (temple_id::text=current_setting(''app.temple_id'',true))',tab);
END LOOP; END $$;
